(let [held (:seon.store/store (#'boot/selected-instance "default")) timed (fn [f] (let [started (System/nanoTime) value (f held)] {:value value :ms (/ (- (System/nanoTime) started) 1e6)})) old (timed #'cluster/loaded-analyzer-digest) new (timed loaded-files-after)] (assert (= (:seon.cluster/loaded-files (:value old)) (:value new))) {:same-files? true :files (count (:value new)) :parent-ms (:ms old) :candidate-ms (:ms new)})
